# ---------------------------------------------------------------------------
# Input ownership / path safety (narrow F01 support).
# ---------------------------------------------------------------------------

def safe_relative_child(root: Path, relative: Any, code: str) -> Path:
    """Lexical containment WITHOUT resolve(): reject absolute, empty, '..'/'.'
    components, then component-walk with lstat so symlinks are seen on the
    ORIGINAL path before any resolution."""
    if not isinstance(relative, str) or not relative:
        raise FailClosed(code)
    parts = Path(relative).parts
    if Path(relative).is_absolute() or any(part in ("..", ".") for part in parts):
        raise FailClosed(code)
    current = root
    for part in parts:
        current = current / part
        try:
            st = os.lstat(current)
        except OSError as exc:
            raise FailClosed(code) from exc
        if stat_module.S_ISLNK(st.st_mode):
            raise FailClosed(code)
    return current


def assert_admin_immutable_file(path: Path, code: str, synthetic: bool) -> None:
    """Root-owned (st_uid==0), regular, non-symlink, not group/other writable."""
    try:
        st = os.lstat(path)
    except OSError as exc:
        raise FailClosed(code) from exc
    if stat_module.S_ISLNK(st.st_mode) or not stat_module.S_ISREG(st.st_mode):
        raise FailClosed(code)
    if synthetic:
        return
    if st.st_uid != 0:
        raise FailClosed(code)
    if st.st_mode & 0o022:
        raise FailClosed(code)
    if os.access(path, os.W_OK):
        raise FailClosed(code)


def assert_admin_immutable_root(root: Path, code: str, synthetic: bool) -> None:
    try:
        st = os.lstat(root)
    except OSError as exc:
        raise FailClosed(code) from exc
    if stat_module.S_ISLNK(st.st_mode) or not stat_module.S_ISDIR(st.st_mode):
        raise FailClosed(code)
    if synthetic:
        return
    if st.st_uid != 0 or st.st_mode & 0o022 or os.access(root, os.W_OK):
        raise FailClosed(code)


def verify_staged_object_file(root: Path, relative: Any, expected_sha256: Any,
                              synthetic: bool, code: str) -> str:
    path = safe_relative_child(root, relative, code)
    assert_admin_immutable_file(path, code, synthetic)
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    actual = digest.hexdigest()
    if not isinstance(expected_sha256, str) or actual != expected_sha256:
        raise FailClosed(code)
    return actual


def frozen_manifest_hash_set(manifest_document: Any) -> set[str]:
    """Collect every 64-hex sha256 value in the frozen PC6 executable data
    manifest / revision lineage so staged objects can be membership-verified
    mechanically (F01-A)."""
    found: set[str] = set()

    def walk(node: Any) -> None:
        if isinstance(node, dict):
            for value in node.values():
                walk(value)
        elif isinstance(node, list):
            for value in node:
                walk(value)
        elif isinstance(node, str) and len(node) == 64 and \
                all(c in "0123456789abcdef" for c in node):
            found.add(node)

    walk(manifest_document)
    return found


def verify_staged_inventory_against_manifest(staged_sha256s: Iterable[str],
                                             manifest_hash_set: set[str]) -> None:
    for value in staged_sha256s:
        if value not in manifest_hash_set:
            raise FailClosed("PC6_STAGED_OBJECT_NOT_IN_FROZEN_MANIFEST")


