def derive_features(source: Mapping[str, Any], grid_ts_us: list[int], kind: str,
                    header: Mapping[str, Any],
                    candidates_by_id: Mapping[str, Mapping[str, Any]] | None = None,
                    order: list[str] | None = None) -> dict[str, Any]:
    symbols = sorted(source["symbols"])
    histories: dict[str, dict[str, list[float]]] = {
        symbol: {"basis": [], "spot_returns": [], "perp_returns": [],
                 "quote_volume": [], "signed_quote_volume": []}
        for symbol in symbols
    }
    last_close: dict[str, tuple[float, float] | None] = {symbol: None for symbol in symbols}
    cohorts: list[dict[str, Any]] = []
    for index, ts in enumerate(grid_ts_us):
        base_features: dict[str, float] = {}
        defined_now: dict[str, bool] = {}
        for symbol in symbols:
            table = source["symbols"][symbol]
            perp = _snapshot(table["perp_bars"], ts)
            spot = _snapshot(table["spot_bars"], ts)
            defined = perp is not None and spot is not None and \
                float(perp["close"]) > 0 and float(spot["close"]) > 0
            defined_now[symbol] = defined
            if not defined:
                last_close[symbol] = None
                continue
            perp_close = float(perp["close"])
            spot_close = float(spot["close"])
            basis = float(evaluator.log_basis(FLOAT(perp_close), FLOAT(spot_close)))
            history = histories[symbol]
            history["basis"].append(basis)
            previous = last_close[symbol]
            if previous is not None:
                history["perp_returns"].append(perp_close / previous[0] - 1.0)
                history["spot_returns"].append(spot_close / previous[1] - 1.0)
            last_close[symbol] = (perp_close, spot_close)
            volume = perp.get("quote_volume")
            signed = perp.get("signed_quote_volume")
            if isinstance(volume, (int, float)) and math.isfinite(float(volume)) and \
                    isinstance(signed, (int, float)) and math.isfinite(float(signed)):
                history["quote_volume"].append(float(volume))
                history["signed_quote_volume"].append(float(signed))
            base_features[symbol] = basis
        cohort: dict[str, Any] = {
            "cohort_id": index,
            "decision_ts_utc": format_utc(ts),
            "decision_us": ts,
            "features": dict(sorted(base_features.items())),
        }
        if kind == "W1":
            if candidates_by_id is None or order is None:
                raise FailClosed("W1_CANDIDATE_SET_REQUIRED")
            candidate_features: dict[str, dict[str, float]] = {}
            for candidate_id in order:
                candidate = candidates_by_id[candidate_id]
                core = candidate.get("signal_core")
                lookback = candidate_lookback_days(candidate)
                values: dict[str, float] = {}
                for symbol in symbols:
                    if not defined_now[symbol]:
                        continue
                    value = _candidate_feature_value(core, histories[symbol], lookback)
                    if value is not None:
                        values[symbol] = value
                candidate_features[candidate_id] = dict(sorted(values.items()))
            cohort["candidate_features"] = candidate_features
        cohorts.append(cohort)
    grid_identity = validate_decision_grid(grid_ts_us, kind,
                                           os.environ.get("P5_SYNTHETIC_MODE") == "1")
    horizons = (8,) if kind == "T1" else W1_HORIZONS
    document = {
        "schema": FEATURES_SCHEMA,
        "kind": kind,
        "decision_grid": grid_identity,
        "allowed_label_end_us_by_horizon": {
            str(h): allowed_label_end_us(kind, h) for h in horizons
        },
        "cohorts": cohorts,
    }
    document.update(dict(header))
    return document


def _candidate_feature_value(core: Any, history: Mapping[str, list[float]],
                             lookback_days: int | None) -> float | None:
    minimum = _MIN_HISTORY.get(core)
    basis_len = len(history["basis"])
    if minimum is not None and basis_len < minimum:
        return None
    if minimum is None:
        if lookback_days is None:
            return None
        needed = _CYCLES_PER_DAY * lookback_days
        required_fields = {
            "BASIS_PERSISTENCE_L": ("basis",),
            "BM_EQ70_L": ("spot_returns", "perp_returns"),
            "PV_L": ("quote_volume",),
            "PV_VAR_L": ("quote_volume",),
            "PV_IMB_L": ("signed_quote_volume",),
            "PV_IMB_VAR_L": ("signed_quote_volume",),
            "DAMIHUD_L": ("quote_volume", "perp_returns"),
        }.get(core)
        if required_fields is None:
            raise FailClosed("W1_CANDIDATE_CORE_UNKNOWN")
        if any(len(history[field]) < needed for field in required_fields):
            return None
    arrays = {key: np.asarray(values, dtype=np.float64)
              for key, values in history.items()}
    try:
        value = evaluator.feature_value(str(core), arrays, lookback_days)
    except evaluator.EvaluationError:
        return None
    result = float(value)
    if not math.isfinite(result):
        return None
    return result


